 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx]!=0 and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            mask=[[0]*(c1-c0+1) for _ in range(r1-r0+1)]
            for y,x in cells: mask[y-r0][x-c0]=grid[y][x]
            comps.append((r0,c0,mask))
    # The drawing is built by overlaying the two left-side motifs, centered
    # in a common canvas; retain their visible foreground.
    comps.sort(key=lambda z:(z[1],z[0]))
    chosen=sorted(comps, key=lambda z:(z[1], z[0]))[:2]
    mh=max(len(m) for _,_,m in chosen); mw=max(len(m[0]) for _,_,m in chosen)
    out=[[0]*mw for _ in range(mh)]
    for _,_,m in chosen:
        oy=(mh-len(m))//2; ox=(mw-len(m[0]))//2
        for y,row in enumerate(m):
            for x,v in enumerate(row):
                if v: out[oy+y][ox+x]=v
    return out

if __name__ == '__main__':
    pass
